import { component, delay } from 'imp'
import { track } from 'imp/analytics'
import { a, article, div, el, h1, header, html, img, nav } from 'imp/html'
import { codeBlock } from 'imp/std/display'
import { hideComments, showComments } from '../comments.js'
import { articleBySlug, categoryBySlug } from '../data.js'
import { scrollToFragment } from '../links.js'
import { siteCss } from '../styles/site.js'

// One article. The area module of each article (src/content/articles/<slug>.js, generated by
// cargo content) renders it with the HTML of its body and its code blocks, so a page downloads only
// the article it shows.
// An invisible point of the body of the article: its middle or its end. The outcomes of reading go
// out when it comes into view.
const readMarker = (place) =>
  div({
    'aria-hidden': 'true',
    style: {
      position: 'absolute',
      insetInlineStart: '0',
      inlineSize: '1px',
      blockSize: '1px',
      ...place,
    },
  })

export const articlePage = component('blog-article-page', {
  styles: siteCss,
  setup: (self, slug, content, code = []) => {
    const item = articleBySlug(slug)
    const category = categoryBySlug(item.category)
    const categoryName = category?.name ?? item.category

    // The previous article, or the category when this is the first one
    const prev = item.prev ?? { title: `Back to ${categoryName}`, url: category.url }
    // The next article, or the next category when this is the last one
    const next =
      item.next
      ?? (item.nextCategory && { title: item.nextCategory.name, url: item.nextCategory.url })

    // The body is HTML that cargo content rendered from the Markdown of the article. Each code
    // block of it is a <div data-code="N"> placeholder for a codeBlock that highlights code[N].
    const body = html(content)
    for (const placeholder of body.querySelectorAll('[data-code]')) {
      placeholder.replaceWith(codeBlock(code[Number(placeholder.dataset.code)]))
    }
    for (const video of body.querySelectorAll('video')) {
      video.addEventListener('loadedmetadata', () => {
        if (video.videoWidth > video.videoHeight) video.classList.add('horizontal-video')
      })
    }

    return article(
      { class: 'article-page' },
      div(
        { class: 'article-top' },
        a({ href: category.url, class: 'article-category-tag' }, categoryName),
      ),
      nav(
        { class: 'article-top-nav' },
        a({ href: prev.url, class: 'article-top-nav-link' }, `← ${prev.title}`),
        next && a({ href: next.url, class: 'article-top-nav-link' }, `${next.title} →`),
      ),
      header(
        h1(item.title),
        div(
          { class: 'article-meta' },
          'Updated at: ',
          el('time', { datetime: item.date }, item.dateLong),
        ),
      ),
      item.image && div({ class: 'article-hero' }, img({ src: item.image, alt: item.title })),
      div(
        { class: 'article-content', style: { position: 'relative' } },
        body,
        (self.halfway = readMarker({ insetBlockStart: '50%' })),
        (self.end = readMarker({ insetBlockEnd: '0' })),
      ),
      div(
        { class: 'article-footer' },
        a({ href: prev.url, class: 'btn btn-secondary' }, `← ${prev.title}`),
        next && a({ href: next.url, class: 'btn btn-secondary' }, `${next.title} →`),
      ),
    )
  },
  onMount: (self, slug) => {
    showComments(slug)
    // The outcomes of reading, at most one of each per page view. The record of an outcome carries
    // the page, /articles/<category>/<slug>, so it tells the article and its category. The end
    // counts as the middle too, for a reader who jumps to the end.
    let halfway = false
    const readHalfway = () => {
      if (halfway) return
      halfway = true
      track('blog.read-halfway')
    }
    self.reading = new IntersectionObserver((entries) => {
      for (const { isIntersecting, target } of entries) {
        if (!isIntersecting) continue
        self.reading.unobserve(target)
        readHalfway()
        if (target === self.end) track('blog.read-full')
      }
    })
    self.reading.observe(self.halfway)
    self.reading.observe(self.end)
    // A link to a section of the article: the router scrolls to the top first
    if (location.hash) delay(self, 0, () => scrollToFragment(self.host.shadowRoot, location.hash))
  },
  onRemove: (self) => {
    self.reading?.disconnect()
    hideComments()
  },
})
